query GetAccount {
  account { id email backupEmail name avatar timezone createdAt preferences { timeFormat startOfWeek defaultScheduleOption } organizations { id name } }
}

query ListOrganizations($filter: OrganizationFilterInput) {
  account { organizations(filter: $filter) { id name ownerEmail channelCount members { totalCount } limits { channels members ideas ideaGroups tags postTemplates scheduledPosts scheduledStoriesPerChannel scheduledThreadsPerChannel } } }
}

query ListChannels($input: ChannelsInput!) {
  channels(input: $input) { id name displayName descriptor service type serviceId avatar externalLink organizationId timezone isDisconnected isLocked isQueuePaused products allowedActions createdAt updatedAt postingSchedule { day paused times } }
}

query GetChannel($input: ChannelInput!) {
  channel(input: $input) { id name displayName descriptor service type serviceId avatar externalLink organizationId timezone isDisconnected isLocked isQueuePaused products allowedActions createdAt updatedAt postingSchedule { day paused times } linkShortening { isEnabled } postingGoal { goal sentCount scheduledCount status periodStart periodEnd } metadata { __typename ... on PinterestMetadata { boards { id serviceId name description url } } } }
}

query GetConfiguration($input: ConfigurationInput!) {
  configuration(input: $input) { channels { channelId service channelType authorizationStatus { feature status reason } content { configurationContentTypes supportedProperties } } services { service channelType content { configurationContentTypes supportedProperties } } }
}

query ListPosts($input: PostsInput!, $first: Int, $after: String) {
  posts(input: $input, first: $first, after: $after) { edges { cursor node { id text status dueAt sentAt createdAt updatedAt channelId channelService shareMode schedulingType isCustomScheduled sharedNow externalLink via ideaId allowedActions tags { id name color } assets { id type mimeType source thumbnail } error { message supportUrl } author { id name email } } } pageInfo { hasNextPage endCursor } }
}

query GetPost($input: PostInput!) {
  post(input: $input) { id text status dueAt sentAt createdAt updatedAt channelId channelService shareMode schedulingType isCustomScheduled sharedNow externalLink via ideaId allowedActions tags { id name color } assets { id type mimeType source thumbnail } error { message supportUrl } author { id name email } notes { id text type createdAt author { name } } }
}

mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) { __typename ... on PostActionSuccess { post { id text status dueAt sentAt createdAt updatedAt channelId channelService shareMode schedulingType isCustomScheduled sharedNow externalLink via ideaId allowedActions tags { id name color } assets { id type mimeType source thumbnail } error { message supportUrl } author { id name email } } } ... on MutationError { message } }
}

mutation EditPost($input: EditPostInput!) {
  editPost(input: $input) { __typename ... on PostActionSuccess { post { id text status dueAt sentAt createdAt updatedAt channelId channelService shareMode schedulingType isCustomScheduled sharedNow externalLink via ideaId allowedActions tags { id name color } assets { id type mimeType source thumbnail } error { message supportUrl } author { id name email } } } ... on MutationError { message } }
}

mutation DeletePost($input: DeletePostInput!) {
  deletePost(input: $input) { __typename ... on DeletePostSuccess { id } ... on MutationError { message } }
}

mutation MovePostInQueue($input: MovePostInQueueInput!) {
  movePostInQueue(input: $input) { __typename ... on PostActionSuccess { post { id text status dueAt sentAt createdAt updatedAt channelId channelService shareMode schedulingType isCustomScheduled sharedNow externalLink via ideaId allowedActions tags { id name color } assets { id type mimeType source thumbnail } error { message supportUrl } author { id name email } } } ... on MutationError { message } }
}

query DailyPostingLimits($input: DailyPostingLimitsInput!) {
  dailyPostingLimits(input: $input) { channelId limit sent scheduled isAtLimit }
}

query ListIdeas($input: IdeasInput!, $first: Int, $after: String) {
  ideas(input: $input, first: $first, after: $after) { edges { cursor node { id organizationId groupId position createdAt updatedAt content { title text date aiAssisted services tags { id name color } media { id url type alt thumbnailUrl } } } } pageInfo { hasNextPage endCursor } }
}

query IdeaGroups($input: IdeaGroupsInput!) {
  ideaGroups(input: $input) { id name isLocked }
}

mutation CreateIdea($input: CreateIdeaInput!) {
  createIdea(input: $input) { __typename ... on Idea { id organizationId groupId position createdAt updatedAt content { title text date aiAssisted services tags { id name color } media { id url type alt thumbnailUrl } } } ... on IdeaResponse { refreshIdeas idea { id organizationId groupId position createdAt updatedAt content { title text date aiAssisted services tags { id name color } media { id url type alt thumbnailUrl } } } } ... on MutationError { message } }
}

query ListTags($input: TagsInput!, $first: Int, $after: String) {
  tagsV2(input: $input, first: $first, after: $after) { totalCount edges { cursor node { id name color colorName isLocked } } pageInfo { hasNextPage endCursor } }
}

query GetTag($input: TagByIdInput!) {
  tag(input: $input) { id name color colorName isLocked }
}

mutation CreateTag($input: CreateTagInput!) {
  createTag(input: $input) { __typename ... on TagActionSuccess { tag { id name color colorName isLocked } } ... on MutationError { message } }
}

mutation UpdateTag($input: UpdateTagInput!) {
  updateTag(input: $input) { __typename ... on TagActionSuccess { tag { id name color colorName isLocked } } ... on MutationError { message } }
}

mutation DeleteTag($input: DeleteTagInput!) {
  deleteTag(input: $input) { __typename ... on DeleteTagActionSuccess { id } ... on MutationError { message } }
}

query ListSnippets($input: SnippetsInput!, $first: Int, $after: String) {
  snippets(input: $input, first: $first, after: $after) { edges { cursor node { id name text } } pageInfo { hasNextPage endCursor } }
}

mutation CreateSnippet($input: CreateSnippetInput!) {
  createSnippet(input: $input) { __typename ... on CreateSnippetSuccess { snippet { id name text } } ... on MutationError { message } }
}

mutation UpdateSnippet($input: UpdateSnippetInput!) {
  updateSnippet(input: $input) { __typename ... on UpdateSnippetSuccess { snippet { id name text } } ... on MutationError { message } }
}

mutation DeleteSnippet($input: DeleteSnippetInput!) {
  deleteSnippet(input: $input) { __typename ... on DeleteSnippetSuccess { id } ... on MutationError { message } }
}

query ListPostTemplates($input: PostTemplatesInput!, $first: Int, $after: String) {
  postTemplates(input: $input, first: $first, after: $after) { totalCount edges { cursor node { id title body description emoji visibility organizationId createdAt updatedAt } } pageInfo { hasNextPage endCursor } }
}

query GetPostTemplate($input: PostTemplateInput!) {
  postTemplate(input: $input) { id title body description emoji visibility organizationId createdAt updatedAt }
}

mutation CreatePostTemplate($input: CreatePostTemplateInput!) {
  createPostTemplate(input: $input) { __typename ... on CreatePostTemplateSuccess { postTemplate { id title body description emoji visibility organizationId createdAt updatedAt } } ... on MutationError { message } }
}

mutation UpdatePostTemplate($input: UpdatePostTemplateInput!) {
  updatePostTemplate(input: $input) { __typename ... on UpdatePostTemplateSuccess { postTemplate { id title body description emoji visibility organizationId createdAt updatedAt } } ... on MutationError { message } }
}

mutation DeletePostTemplate($input: DeletePostTemplateInput!) {
  deletePostTemplate(input: $input) { __typename ... on MutationError { message } }
}

query ListContentItems($input: ContentItemsInput!, $first: Int, $after: String) {
  contentItems(input: $input, first: $first, after: $after) { totalCount edges { cursor node { id title targetDate createdAt organizationId allowedActions tags { id name color } author { id name email } body { __typename ... on DraftContent { id text aiAssisted assets { type source thumbnail mimeType } } ... on PostContent { posts { id channelId channelService status dueAt text } } } } } pageInfo { hasNextPage endCursor } }
}

query GetContentItem($input: ContentItemInput!) {
  contentItem(input: $input) { id title targetDate createdAt organizationId allowedActions tags { id name color } author { id name email } body { __typename ... on DraftContent { id text aiAssisted assets { type source thumbnail mimeType } } ... on PostContent { posts { id channelId channelService status dueAt text } } } }
}

mutation CreateContentItem($input: CreateContentItemInput!) {
  createContentItem(input: $input) { __typename ... on CreateContentItemSuccess { content { id title targetDate createdAt organizationId allowedActions tags { id name color } author { id name email } body { __typename ... on DraftContent { id text aiAssisted assets { type source thumbnail mimeType } } ... on PostContent { posts { id channelId channelService status dueAt text } } } } } ... on CreateContentItemFailure { message errors { __typename ... on MutationError { message } } } }
}

mutation CreateContentItemDraft($input: CreateContentItemDraftInput!) {
  createContentItemDraft(input: $input) { __typename ... on CreateContentItemDraftSuccess { contentItem { id title targetDate createdAt organizationId allowedActions tags { id name color } author { id name email } body { __typename ... on DraftContent { id text aiAssisted assets { type source thumbnail mimeType } } ... on PostContent { posts { id channelId channelService status dueAt text } } } } } ... on CreateContentItemDraftFailure { message errors { __typename ... on MutationError { message } } } }
}

mutation UpdateContentItem($input: UpdateContentItemInput!) {
  updateContentItem(input: $input) { __typename ... on UpdateContentItemSuccess { contentItem { id title targetDate createdAt organizationId allowedActions tags { id name color } author { id name email } body { __typename ... on DraftContent { id text aiAssisted assets { type source thumbnail mimeType } } ... on PostContent { posts { id channelId channelService status dueAt text } } } } } ... on UpdateContentItemFailure { message errors { __typename ... on MutationError { message } } } }
}

mutation UpdateContentItemDraft($input: UpdateContentItemDraftInput!) {
  updateContentItemDraft(input: $input) { __typename ... on UpdateContentItemDraftSuccess { contentItem { id title targetDate createdAt organizationId allowedActions tags { id name color } author { id name email } body { __typename ... on DraftContent { id text aiAssisted assets { type source thumbnail mimeType } } ... on PostContent { posts { id channelId channelService status dueAt text } } } } } ... on UpdateContentItemDraftFailure { message errors { __typename ... on MutationError { message } } } }
}

mutation PromoteDraft($input: PromoteContentItemDraftToPostsInput!) {
  promoteContentItemDraftToPosts(input: $input) { __typename ... on PromoteContentItemDraftToPostsSuccess { contentItem { id title targetDate createdAt organizationId allowedActions tags { id name color } author { id name email } body { __typename ... on DraftContent { id text aiAssisted assets { type source thumbnail mimeType } } ... on PostContent { posts { id channelId channelService status dueAt text } } } } } ... on PromoteContentItemDraftToPostsFailure { message errors { __typename ... on MutationError { message } } } }
}

mutation AddPostToContentItem($input: AddPostToContentItemInput!) {
  addPostToContentItem(input: $input) { __typename ... on AddPostToContentItemSuccess { contentItem { id title targetDate createdAt organizationId allowedActions tags { id name color } author { id name email } body { __typename ... on DraftContent { id text aiAssisted assets { type source thumbnail mimeType } } ... on PostContent { posts { id channelId channelService status dueAt text } } } } post { id channelId status } } ... on MutationError { message } }
}

mutation RemovePostFromContentItem($input: RemovePostFromContentItemInput!) {
  removePostFromContentItem(input: $input) { __typename ... on RemovePostFromContentItemSuccess { contentItem { id title targetDate createdAt organizationId allowedActions tags { id name color } author { id name email } body { __typename ... on DraftContent { id text aiAssisted assets { type source thumbnail mimeType } } ... on PostContent { posts { id channelId channelService status dueAt text } } } } post { id channelId status } } ... on MutationError { message } }
}

mutation DeleteContentItem($input: DeleteContentItemInput!) {
  deleteContentItem(input: $input) { __typename ... on DeleteContentItemFailure { message errors { channelId message } } }
}

query TrendingInstagramAudio($input: TrendingInstagramAudioInput!) {
  trendingInstagramAudio(input: $input) { __typename ... on SearchInstagramAudioSuccess { audio { id title type duration displayArtist creatorUsername coverArtworkUrl previewUrl } } ... on ChannelRefreshRequired { message channelIds } }
}

query SearchInstagramAudio($input: SearchInstagramAudioInput!) {
  searchInstagramAudio(input: $input) { __typename ... on SearchInstagramAudioSuccess { audio { id title type duration displayArtist creatorUsername coverArtworkUrl previewUrl } } ... on ChannelRefreshRequired { message channelIds } }
}

query InstagramAudioCatalog($input: InstagramAudioCatalogInput!) {
  instagramAudioCatalog(input: $input) { __typename ... on InstagramAudioCatalogSuccess { failedAudioTypes audio { id title type duration displayArtist creatorUsername coverArtworkUrl previewUrl } } ... on ChannelRefreshRequired { message channelIds } }
}

query SearchInstagramAudioCatalog($input: SearchInstagramAudioCatalogInput!) {
  searchInstagramAudioCatalog(input: $input) { __typename ... on InstagramAudioCatalogSuccess { failedAudioTypes audio { id title type duration displayArtist creatorUsername coverArtworkUrl previewUrl } } ... on ChannelRefreshRequired { message channelIds } }
}

query InstagramAudio($input: InstagramAudioInput!) {
  instagramAudio(input: $input) { __typename ... on InstagramAudioSuccess { audio { id title type duration displayArtist creatorUsername coverArtworkUrl previewUrl } } ... on ChannelRefreshRequired { message channelIds } }
}
